var r = 80; // size of blocks
var h = 1.3; // relative height of blocks

var top = color(250, 100, 50); // block side colors
var right = color(50, 100, 200);
var left = color(100, 20, 120);

var shadow = color(0); // shadows. colors other than black will look weird.
var highlight = color(255); // highlights. colors other than white may look weird
var hl = 1.2; // range 0-2. how much to blow out highlights
var ambient = 0; // range 0-1. ambient light
var drag = 4; // how slowly the light follows the mouse. must be above, or equal to 1

function setup() {
  //createCanvas(900, 600);
  createCanvas(windowWidth, windowHeight);
  noStroke();
}


var mx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
var my = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));

function draw() {

  mx+=((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-mx)/drag;
  my+=((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-my)/drag;

  let x1 = r, x2 = -r/2;
  let y1 = -r, y2 = -r/2;
  let z1 = 0, z2 = r*h;

  let w1 = x1-y1;
  //let w2 = x2-y2;
  let h1 = z1-y1;
  let h2 = z2-y2;


  for (let y = 0; (y-1)*h2<height; y++) {
    for (let x = 0; (x-1)*w1<width; x++) {
      pushMatrix();
      translate(w1*x+h1*(y%2), h2*y);

      let dx = (w1*x+h1*(y%2))-mx;
      let dy = h2*y-my;
      fill(lumin(top, reflect(dx, dy+r)));
      quad(0, 0, 
        x1, x2, 
        x1+y1, x2+y2, 
        y1, y2);

      dx = (w1*x+h1*(y%2))-mx - (x1+x1+z1+z1)/2;
      dy = h2*y-my-(x2+x2+z2+z2)/2;
      let a = 2*PI/3;
      fill(lumin(right, reflect(cos(a)*dx+sin(a)*dy, cos(a)*dy-sin(a)*dx)));
      quad(0, 0, 
        x1, x2, 
        x1+z1, x2+z2, 
        z1, z2);


      dx = (w1*x+h1*(y%2))-mx + (x1+x1+z1+z1)/2;
      dy = h2*y-my-(x2+x2+z2+z2)/2;
      a = -2*PI/3;
      fill(lumin(left, reflect(cos(a)*dx+sin(a)*dy, cos(a)*dy-sin(a)*dx)));
      quad(0, 0, 
        z1, z2, 
        z1+y1, z2+y2, 
        y1, y2);
      popMatrix();
    }
  }
}

function reflect(offset, distance) {
  let d = distance/2/r-0.3;
  let ans = constrain(
    2*(d/(d*d+0.5))/1.41
    /max(1, abs(offset)/r), 
    0, 1);

    ans = (ans+sq(ans))/2;
    return ans;
}

// returns a let with a shadow added based on the light received. 0 is dark, 0.5 returns same color, 1 is blown out
function lumin(base, light) {
  return light<0.5?
    lerpColor(shadow, base, map(light*2, 0, 1, ambient, 1)):
    lerpColor(base, highlight, (light-0.5)*hl);
}
